package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class ModelPcaChecks {
    static int checks;static void check(boolean condition){checks++;if(!condition)throw new AssertionError("Model PCA check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid model PCA accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Random random=new Random(995);double[][] data=new double[120][9];for(var row:data){double a=random.nextGaussian(),b=.4*a+random.nextGaussian(),c=.2*a+.3*b+random.nextGaussian();double[] factors={a,b,c};for(int j=0;j<9;j++)row[j]=(1+j*.2)*(factors[j/3]+.2*random.nextGaussian());}List<String> names=java.util.stream.IntStream.range(0,9).mapToObj(i->"V"+(i+1)).toList();List<PlsSem.Block> blocks=List.of(new PlsSem.Block("A",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("B",new int[]{3,4,5},PlsSem.Mode.A),new PlsSem.Block("C",new int[]{6,7,8},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(1,2));var sem=SemModel.reflective(names,data,blocks,edges,true,false).model();boolean[][] weights=new boolean[9][3],loadings=new boolean[9][3];double[][] initial=new double[9][3];for(int i=0;i<9;i++){weights[i][i/3]=loadings[i][i/3]=true;initial[i][i/3]=1;}loadings[0][1]=true;var gsca=new Gsca.Model(names,List.of("A","B","C"),weights,loadings,new boolean[][]{{false,true,false},{false,false,true},{false,false,false}},initial);
        List<ModelPca.Source> sources=List.of(ModelPca.fromPls(names,blocks),ModelPca.fromSem(sem),ModelPca.fromGsca(gsca));check(sources.get(2).groups().get(1).indicators().equals(List.of("V1","V4","V5","V6")));
        JsonArray cases=new JsonArray();var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();for(var source:sources)for(var retention:ModelPca.Retention.values())for(boolean correlation:new boolean[]{true,false}){if(!correlation&&retention==ModelPca.Retention.KAISER)continue;var options=new ModelPca.Options(correlation,retention,2,.9,new PcaRotation.Options(retention==ModelPca.Retention.VARIANCE?PcaRotation.Method.PROMAX:PcaRotation.Method.VARIMAX,true,1000,1e-9,4));List<Integer> progress=new ArrayList<>();var result=ModelPca.fit(data,names,source,options,progress::add);check(result.groups().size()==4&&progress.equals(List.of(1,2,3,4)));check(result.groups().getFirst().columns().size()==9);for(var group:result.groups()){check(group.pca().retained()>=1&&group.pca().retained()<=group.columns().size());check(group.rotation().converged());if(retention==ModelPca.Retention.KAISER)check(group.pca().retained()==(int)Arrays.stream(group.pca().eigenvalues()).filter(value->value>1).count());}var numeric=new JsonObject();numeric.add("modelPca",gson.toJsonTree(result));var archive=org.brightstats.report.ReportArchive.create("MODEL_PCA_TEST",new JsonObject(),numeric,new JsonArray(),List.of());var restored=org.brightstats.report.ModelPcaReports.point(archive);check(restored.groups().size()==result.groups().size());if(retention==ModelPca.Retention.VARIANCE)check(Double.isNaN(restored.groups().getFirst().rotation().objective()));var item=new JsonObject();item.add("data",gson.toJsonTree(data));item.add("columnNames",gson.toJsonTree(names));item.add("source",gson.toJsonTree(source));item.add("result",gson.toJsonTree(result));item.add("blocks",gson.toJsonTree(blocks));item.add("semModel",gson.toJsonTree(sem));item.add("gscaModel",gson.toJsonTree(gsca));cases.add(item);}
        reject(()->new ModelPca.Options(false,ModelPca.Retention.KAISER,2,.95,PcaRotation.Options.defaults()));reject(()->new ModelPca.Options(true,ModelPca.Retention.FIXED,0,.95,PcaRotation.Options.defaults()));reject(()->ModelPca.fit(data,names,new ModelPca.Source(ModelPca.Context.PLS,List.of("Missing"),List.of()),ModelPca.Options.defaults(),null));reject(()->new ModelPca.Group("Duplicate",List.of("V1","V1")));
        Thread.currentThread().interrupt();try{ModelPca.fit(data,names,sources.getFirst(),ModelPca.Options.defaults(),null);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
